        /**
         * Whether this is money owed, for colour.
         */owed: Bool, 
        /**
         * `"$410 of $2,000 limit used"`, where a limit exists.
         */utilisation: String?) {
        self.id = id
        self.name = name
        self.subtitle = subtitle
        self.amount = amount
        self.owed = owed
        self.utilisation = utilisation
    }

    

    
}

