/**
 * `Render` is far larger than the other variants, which clippy notices. It is
 * deliberate: the whole screen crosses in one action so that the view holds no
 * state to apply a diff against (see the note on `UiAction::Render`). Boxing
 * it would not help — UniFFI copies the payload across the boundary either
 * way, so the indirection would cost an allocation and buy nothing.
 */

public enum Action: Equatable, Hashable {
    
    case toUi(action: UiAction
    )
    case toSource(action: SourceAction
    )





}

#if compiler(>=6)
extension Action: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeAction: FfiConverterRustBuffer {
    typealias SwiftType = Action

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> Action {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .toUi(action: try FfiConverterTypeUiAction.read(from: &buf)
        )
        
        case 2: return .toSource(action: try FfiConverterTypeSourceAction.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: Action, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .toUi(action):
            writeInt(&buf, Int32(1))
            FfiConverterTypeUiAction.write(action, into: &buf)
            
        
        case let .toSource(action):
            writeInt(&buf, Int32(2))
            FfiConverterTypeSourceAction.write(action, into: &buf)
            
        }
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeAction_lift(_ buf: RustBuffer) throws -> Action {
    return try FfiConverterTypeAction.lift(buf)
}

